import sys

class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    n = int(sys.stdin.readline())
    head = None
    tail = None

    for _ in range(n):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            found = False
            while current is not None:
                if current.value == x:
                    found = True
                    break
                current = current.next
            if not found:
                continue
            if current == head:
                if head == tail:
                    head = tail = None
                else:
                    head = head.next
                    head.prev = None
            elif current == tail:
                tail = tail.prev
                tail.next = None
            else:
                prev_node = current.prev
                next_node = current.next
                prev_node.next = next_node
                next_node.prev = prev_node
        elif parts[0] == 'deleteFirst':
            if head is None:
                continue
            if head == tail:
                head = tail = None
            else:
                head = head.next
                head.prev = None
        elif parts[0] == 'deleteLast':
            if tail is None:
                continue
            if head == tail:
                head = tail = None
            else:
                tail = tail.prev
                tail.next = None

    result = []
    current = head
    while current is not None:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

